css:
.load {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
}

.tower {
  display: flex;
  margin-top: 100px;
  gap: 80px;
}

/* The loader */
.loader {
  position: absolute;
  top: 40%;
  left: 50%;
  width: 200px;
  height: 200px;
  margin-top: -100px;
  margin-left: -100px;
  perspective: 600px;
  transform-style: perserve-3d;
}

/* The dot */
.dot {
  position: absolute;
  top: 40%;
  left: 50%;
  width: 100px;
  height: 100px;
  margin-top: -50px;
  margin-left: -50px;
  border-radius: 100px;
  border: 20px solid #d04197;
  transform-style: perserve-3d;
  transform: scale(0) rotateX(60deg);
  animation: dot 3s cubic-bezier(0.67, 0.08, 0.46, 1.5) infinite;
}

.dot:nth-child(2) {
  animation-delay: 200ms;
}

.dot:nth-child(3) {
  animation-delay: 400ms;
}

.dot:nth-child(4) {
  animation-delay: 600ms;
}

.dot:nth-child(5) {
  animation-delay: 800ms;
}

.dot:nth-child(6) {
  animation-delay: 1000ms;
}

.dot:nth-child(7) {
  animation-delay: 1200ms;
}

.dot:nth-child(8) {
  animation-delay: 1400ms;
}

@keyframes dot {
  0% {
    opacity: 0;
    border-color: #df55a3;
    transform: rotateX(60deg) rotateY(45deg) translateZ(-100px) scale(0.1);
  }

  40% {
    opacity: 1;
    transform: rotateX(0deg) rotateY(20deg) translateZ(0) scale(1);
  }

  100% {
    opacity: 0;
    transform: rotateX(60deg) rotateY(-45deg) translateZ(-100px) scale(0.1);
  }
}

.loading {
  font-size: 14px;
  font-weight: 400;
  color: white;
  margin-left: 22px;
  font-family: sans-serif;
  display: inline-flex;
  align-items: center;
}

.dots {
  display: inline-block;
  width: 24px; /* fixed width so text doesn't move */
  text-align: left;
}

.dots::after {
  content: "";
  animation: dots 1.5s infinite;
}

@keyframes dots {
  0% {
    content: "";
  }
  33% {
    content: ".";
  }
  66% {
    content: "..";
  }
  100% {
    content: "...";
  }
}
